string minWindow(string s, string t) {
    unordered_map<char, int> need, window;
    for (char c : t) need[c]++;

    int formed = 0;                 // how many distinct chars are fully covered
    int required = need.size();
    int left = 0, best = INT_MAX, start = 0;

    for (int right = 0; right < s.size(); right++) {
        char c = s[right];
        window[c]++;
        if (need.count(c) && window[c] == need[c]) formed++;

        while (formed == required) {
            if (right - left + 1 < best) {
                best = right - left + 1;
                start = left;
            }
            char d = s[left++];
            window[d]--;
            if (need.count(d) && window[d] < need[d]) formed--;
        }
    }
    if (best == INT_MAX) return "";
    return s.substr(start, best);
}
// O(|s| + |t|)

vector<int> zeroSumSubarray(vector<int>& a) {
    // If the same prefix sum shows up twice, the part in between sums to 0.
    unordered_map<long long, int> firstIndex;
    firstIndex[0] = -1;
    long long sum = 0;

    for (int i = 0; i < a.size(); i++) {
        sum += a[i];
        if (firstIndex.count(sum)) {
            int from = firstIndex[sum] + 1;
            return vector<int>(a.begin() + from, a.begin() + i + 1);
        }
        firstIndex[sum] = i;
    }
    return {};
}
