int jump(vector<int>& nums) {
    int jumps = 0, end = 0, farthest = 0;
    for (int i = 0; i < (int)nums.size() - 1; i++) {
        farthest = max(farthest, i + nums[i]);
        if (i == end) {          // finished this jump, take the next one
            jumps++;
            end = farthest;
        }
    }
    return jumps;
}

// Also return the indexes we land on.
vector<int> jumpWithPath(vector<int>& nums) {
    int n = nums.size();
    if (n <= 1) return {0};

    vector<int> from(n, -1);
    int left = 0, right = 0;
    while (right < n - 1) {
        int farthest = right, who = -1;
        for (int i = left; i <= right; i++) {
            int reach = min(n - 1, i + nums[i]);
            if (reach > farthest) {
                farthest = reach;
                who = i;
            }
        }
        if (who == -1) return {};
        for (int j = right + 1; j <= farthest; j++) from[j] = who;
        left = right + 1;
        right = farthest;
    }

    vector<int> path;
    for (int i = n - 1; i != -1; i = from[i]) path.push_back(i);
    reverse(path.begin(), path.end());
    return path;
}
