string multiply(string num1, string num2) {
    int m = num1.size(), n = num2.size();
    vector<int> prod(m + n, 0);

    for (int i = m - 1; i >= 0; i--) {
        for (int j = n - 1; j >= 0; j--) {
            int sum = (num1[i] - '0') * (num2[j] - '0') + prod[i + j + 1];
            prod[i + j + 1] = sum % 10;
            prod[i + j] += sum / 10;
        }
    }

    string ans;
    for (int d : prod) {
        if (ans.empty() && d == 0) continue;
        ans.push_back('0' + d);
    }
    return ans.empty() ? "0" : ans;
}
