vector<pair<int,int>> pairsWithSum(vector<int>& a, vector<int>& b, int k) {
    unordered_map<int, int> countB;
    for (int x : b) countB[x]++;

    vector<pair<int,int>> ans;
    for (int x : a) {
        int need = k - x;
        int times = countB[need];   // map, not a set, so duplicate 1's both pair
        while (times--) ans.push_back({x, need});
    }
    return ans;
}
