int maxScore(vector<int>& cards, int k) {
    int n = cards.size();
    int sum = 0;
    for (int i = 0; i < k; i++) sum += cards[i];

    int best = sum;
    for (int i = 0; i < k; i++) {
        sum += cards[n - 1 - i];
        sum -= cards[k - 1 - i];
        best = max(best, sum);
    }
    return best;
}
