vector<int> searchRange(vector<int>& nums, int target) {
    auto search = [&](bool findLeft) {
        int lo = 0, hi = (int)nums.size() - 1, ans = -1;
        while (lo <= hi) {
            int mid = lo + (hi - lo) / 2;
            if (nums[mid] == target) {
                ans = mid;
                if (findLeft) hi = mid - 1;
                else lo = mid + 1;
            } else if (nums[mid] < target) {
                lo = mid + 1;
            } else {
                hi = mid - 1;
            }
        }
        return ans;
    };
    return {search(true), search(false)};
}
