ListNode* reverseKGroup(ListNode* head, int k) {
    ListNode* node = head;
    for (int i = 0; i < k; i++) {
        if (!node) return head;   // not enough nodes left, leave them as they are
        node = node->next;
    }

    ListNode* prev = nullptr;
    ListNode* cur = head;
    for (int i = 0; i < k; i++) {
        ListNode* next = cur->next;
        cur->next = prev;
        prev = cur;
        cur = next;
    }
    head->next = reverseKGroup(cur, k);
    return prev;
}
