Node* copyRandomList(Node* head) {
    if (!head) return nullptr;

    unordered_map<Node*, Node*> copy;
    for (Node* cur = head; cur; cur = cur->next) {
        copy[cur] = new Node{cur->val, nullptr, nullptr};
    }
    for (Node* cur = head; cur; cur = cur->next) {
        if (cur->next) copy[cur]->next = copy[cur->next];
        if (cur->random) copy[cur]->random = copy[cur->random];
    }
    return copy[head];
}
