Node* connect(Node* root) {
    if (!root) return nullptr;

    Node* level = root;
    while (level->left) {
        Node* cur = level;
        while (cur) {
            cur->left->next = cur->right;
            if (cur->next) cur->right->next = cur->next->left;
            cur = cur->next;
        }
        level = level->left;
    }
    return root;
}
