vector<vector<int>> verticalOrder(TreeNode* root) {
    vector<vector<int>> ans;
    if (!root) return ans;

    map<int, vector<int>> col;
    queue<pair<TreeNode*, int>> q;
    q.push({root, 0});

    while (!q.empty()) {
        auto [node, c] = q.front();
        q.pop();
        col[c].push_back(node->val);
        if (node->left) q.push({node->left, c - 1});
        if (node->right) q.push({node->right, c + 1});
    }
    for (auto& [c, vals] : col) ans.push_back(vals);
    return ans;
}
