bool pathExists(vector<vector<int>>& grid) {
    int n = grid.size(), m = grid[0].size();
    if (grid[0][0] == 1 || grid[n - 1][m - 1] == 1) return false;

    queue<pair<int, int>> q;
    q.push({0, 0});
    grid[0][0] = 1;   // 0 open, 1 wall. Marking visited as 1 is enough here.

    int dr[] = {1, -1, 0, 0};
    int dc[] = {0, 0, 1, -1};
    while (!q.empty()) {
        auto [r, c] = q.front();
        q.pop();
        if (r == n - 1 && c == m - 1) return true;
        for (int k = 0; k < 4; k++) {
            int nr = r + dr[k], nc = c + dc[k];
            if (nr < 0 || nc < 0 || nr >= n || nc >= m) continue;
            if (grid[nr][nc] == 1) continue;
            grid[nr][nc] = 1;
            q.push({nr, nc});
        }
    }
    return false;
}
