int minCutDiff(int n, vector<vector<int>>& edges, vector<int>& values) {
    vector<vector<int>> adj(n);
    for (auto& e : edges) {
        adj[e[0]].push_back(e[1]);
        adj[e[1]].push_back(e[0]);
    }

    long long total = 0;
    for (int v : values) total += v;

    long long best = LLONG_MAX;
    function<long long(int, int)> dfs = [&](int u, int parent) {
        long long sub = values[u];
        for (int v : adj[u]) {
            if (v != parent) sub += dfs(v, u);
        }
        if (parent != -1) {
            long long other = total - sub;
            best = min(best, llabs(sub - other));
        }
        return sub;
    };
    dfs(0, -1);
    return (int)best;
}
// Cut one edge. The two sides are the subtree sum and total minus that.

void dfs(int u, int parent, vector<vector<int>>& g,
         vector<int>& tin, vector<int>& low, vector<vector<int>>& bridges, int& timer) {
    tin[u] = low[u] = timer++;
    for (int v : g[u]) {
        if (v == parent) continue;
        if (tin[v] == -1) {
            dfs(v, u, g, tin, low, bridges, timer);
            low[u] = min(low[u], low[v]);
            if (low[v] > tin[u]) bridges.push_back({u, v});
        } else {
            low[u] = min(low[u], tin[v]);
        }
    }
}

vector<vector<int>> criticalConnections(int n, vector<vector<int>>& edges) {
    vector<vector<int>> g(n);
    for (auto& e : edges) {
        g[e[0]].push_back(e[1]);
        g[e[1]].push_back(e[0]);
    }
    vector<int> tin(n, -1), low(n);
    vector<vector<int>> bridges;
    int timer = 0;
    for (int i = 0; i < n; i++) {
        if (tin[i] == -1) dfs(i, -1, g, tin, low, bridges, timer);
    }
    return bridges;
}
