int maxSumIncreasing(vector<int>& arr) {
    if (arr.empty()) return 0;
    int n = arr.size();
    vector<int> dp = arr;   // best sum of an increasing subsequence ending here
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < i; j++) {
            if (arr[j] < arr[i]) dp[i] = max(dp[i], dp[j] + arr[i]);
        }
    }
    return *max_element(dp.begin(), dp.end());
}
