vector<string> permutations(string s) {
    sort(s.begin(), s.end());
    vector<string> ans;
    string cur;
    vector<bool> used(s.size(), false);

    function<void()> rec = [&]() {
        if (cur.size() == s.size()) {
            ans.push_back(cur);
            return;
        }
        for (int i = 0; i < s.size(); i++) {
            if (used[i]) continue;
            if (i > 0 && s[i] == s[i - 1] && !used[i - 1]) continue;
            used[i] = true;
            cur.push_back(s[i]);
            rec();
            cur.pop_back();
            used[i] = false;
        }
    };
    rec();
    return ans;
}
