long long diceWays(int dice, int faces, int target) {
    vector<vector<long long>> dp(dice + 1, vector<long long>(target + 1, 0));
    dp[0][0] = 1;

    for (int d = 1; d <= dice; d++) {
        for (int sum = 1; sum <= target; sum++) {
            for (int face = 1; face <= faces && face <= sum; face++) {
                dp[d][sum] += dp[d - 1][sum - face];
            }
        }
    }
    return dp[dice][target];
}
// dp[d][sum] = ways to reach sum with d dice.

vector<string> generateParenthesis(int n) {
    vector<string> ans;
    string cur;

    function<void(int, int)> rec = [&](int open, int close) {
        if (cur.size() == 2 * n) {
            ans.push_back(cur);
            return;
        }
        if (open < n) {
            cur.push_back('(');
            rec(open + 1, close);
            cur.pop_back();
        }
        if (close < open) {
            cur.push_back(')');
            rec(open, close + 1);
            cur.pop_back();
        }
    };
    rec(0, 0);
    return ans;
}
// Add '(' while we still can. Add ')' only when it won't outnumber '('.

string longestRepeating(string s) {
    int n = s.size();
    vector<vector<int>> dp(n + 1, vector<int>(n + 1, 0));
    int best = 0, endAt = 0;

    for (int i = 1; i <= n; i++) {
        for (int j = i + 1; j <= n; j++) {
            if (s[i - 1] != s[j - 1]) continue;
            if (dp[i - 1][j - 1] < (j - i)) {
                dp[i][j] = dp[i - 1][j - 1] + 1;
                if (dp[i][j] > best) {
                    best = dp[i][j];
                    endAt = i;
                }
            }
        }
    }
    return s.substr(endAt - best, best);
}
