class FreqStack {
    unordered_map<int, int> freq;
    unordered_map<int, vector<int>> stacks;  // stacks[f] = values that currently appear f times
    int maxFreq = 0;
public:
    void push(int x) {
        freq[x]++;
        stacks[freq[x]].push_back(x);
        maxFreq = max(maxFreq, freq[x]);
    }
    int pop() {
        int x = stacks[maxFreq].back();
        stacks[maxFreq].pop_back();
        freq[x]--;
        if (stacks[maxFreq].empty()) maxFreq--;
        return x;
    }
};
// Pop the most frequent value. Ties go to the one pushed later, which is the back of that stack.

int findKthLargest(vector<int>& nums, int k) {
    priority_queue<int, vector<int>, greater<int>> heap;
    for (int x : nums) {
        heap.push(x);
        if (heap.size() > k) heap.pop();
    }
    return heap.top();
}
