class MyHashMap {
    static class Node {
        int key, val;
        Node next;
        Node(int key, int val, Node next) {
            this.key = key;
            this.val = val;
            this.next = next;
        }
    }

    private Node[] buckets = new Node[16];
    private int size = 0;

    public synchronized void put(int key, int val) {
        int i = index(key);
        for (Node n = buckets[i]; n != null; n = n.next) {
            if (n.key == key) {
                n.val = val;
                return;
            }
        }
        buckets[i] = new Node(key, val, buckets[i]);
        size++;
        if (size > buckets.length * 0.75) resize();
    }

    public synchronized Integer get(int key) {
        for (Node n = buckets[index(key)]; n != null; n = n.next) {
            if (n.key == key) return n.val;
        }
        return null;
    }

    public synchronized void remove(int key) {
        int i = index(key);
        Node prev = null;
        for (Node n = buckets[i]; n != null; n = n.next) {
            if (n.key == key) {
                if (prev == null) buckets[i] = n.next;
                else prev.next = n.next;
                size--;
                return;
            }
            prev = n;
        }
    }

    private void resize() {
        Node[] old = buckets;
        buckets = new Node[old.length * 2];
        for (Node head : old) {
            for (Node n = head; n != null; n = n.next) {
                int i = index(n.key);
                buckets[i] = new Node(n.key, n.val, buckets[i]);
            }
        }
    }

    // length stays a power of 2, so & (length - 1) is the bucket.
    private int index(int key) {
        return (key ^ (key >>> 16)) & (buckets.length - 1);
    }
}

import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

class HtmlWordCounter {
    private final ExecutorService pool;

    HtmlWordCounter(int threads) {
        pool = Executors.newFixedThreadPool(threads);
    }

    List<Hit> countAll(List<String> urls, String keyword) {
        List<CompletableFuture<Hit>> jobs = new ArrayList<>();
        for (String url : urls) {
            jobs.add(CompletableFuture.supplyAsync(() -> countOne(url, keyword), pool));
        }
        List<Hit> ans = new ArrayList<>();
        for (CompletableFuture<Hit> job : jobs) ans.add(job.join());
        return ans;
    }

    private Hit countOne(String url, String keyword) {
        try {
            String html = fetchHtml(url);
            return new Hit(url, keyword, count(html, keyword));
        } catch (Exception e) {
            return new Hit(url, keyword, -1);
        }
    }

    private long count(String text, String keyword) {
        long n = 0;
        int from = 0;
        while (true) {
            int at = text.indexOf(keyword, from);
            if (at < 0) return n;
            n++;
            from = at + keyword.length();
        }
    }

    private String fetchHtml(String url) throws Exception {
        // HTTP GET. A throw here is caught above and stored as -1.
        throw new IOException(url);
    }

    record Hit(String url, String keyword, long count) {}
}

import java.util.concurrent.atomic.AtomicReference;

class ConfigBuilder {
    static class Config {
        final String name;
        final String role;
        Config(String name, String role) {
            this.name = name;
            this.role = role;
        }
    }

    private final AtomicReference<Config> cur = new AtomicReference<>(new Config(null, null));

    void setName(String name) {
        while (true) {
            Config old = cur.get();
            Config next = new Config(name, old.role);
            if (cur.compareAndSet(old, next)) return;
        }
    }

    void setRole(String role) {
        while (true) {
            Config old = cur.get();
            Config next = new Config(old.name, role);
            if (cur.compareAndSet(old, next)) return;
        }
    }

    Config build() {
        return cur.get();
    }
}
