// Move n-1 out of the way, move the biggest disk, then put n-1 on top.

int findUnsortedSubarray(vector<int>& nums) {
    int n = nums.size();
    int right = -1, mx = INT_MIN;
    for (int i = 0; i < n; i++) {
        mx = max(mx, nums[i]);
        if (nums[i] < mx) right = i;
    }

    int left = 0, mn = INT_MAX;
    for (int i = n - 1; i >= 0; i--) {
        mn = min(mn, nums[i]);
        if (nums[i] > mn) left = i;
    }
    if (right == -1) return 0;
    return right - left + 1;
}
// right = last index smaller than something on its left. left = first index bigger than something on its right.

int josephus(int n, int k) {
    int pos = 0;
    for (int i = 2; i <= n; i++) {
        pos = (pos + k) % i;
    }
    return pos + 1;
}
// After removing one person, the next start is k seats ahead in a circle of the remaining people.

int totalJumps(vector<int>& walls, int H, int L) {
    int jumps = 0;
    for (int w : walls) {
        if (w <= H) {
            jumps++;
            continue;
        }
        if (H <= L) return -1;

        int height = 0;
        while (height < w) {
            height += H;
            jumps++;
            if (height >= w) break;
            height -= L;
        }
    }
    return jumps;
}
